  if (KIND === 'nim') return [1,2,3].filter(n=>n<=s.board[0]).map(take=>({take}));
  if (KIND === 'mancala') return s.board.flatMap((n,pit)=>n&&pit>=(s.turn?7:0)&&pit<(s.turn?13:6)?[{pit}]:[]);
